    const UINT x=h.x>desc.Width-h.width?desc.Width-h.width:h.x;
    const UINT y=h.y>desc.Height-h.height?desc.Height-h.height:h.y;
    if(t.verbose) {char line[256];snprintf(line,sizeof(line),"osd-panel-desc w=%lu h=%lu fmt=Pbgra32 pos=%u,%u requested=%lu,%lu target=%u,%u msaa=%u mode=%u generation=%lu",h.width,h.height,x,y,h.x,h.y,desc.Width,desc.Height,desc.MultiSampleType,PanelOsd::PanelMode(h)?1u:0u,h.generation);t.Line(line);}
